        type: "p",
        text: "Um GlobalId é a identidade permanente de um elemento IFC — ele sobrevive a fusões de modelo, atualizações de versão e migrações de software. Quando dois elementos compartilham o mesmo GUID, toda ferramenta que depende de referências estáveis (fluxos de trabalho em BCF, rastreamento de vínculos no Revit, versionamento na CDE) quebra silenciosamente.",
