    slug: "ifc2x3-vs-ifc4",
    title: "IFC2x3 vs IFC4: vale a pena atualizar seu schema de exportação?",
    excerpt: "A maioria dos projetos de BIM ainda entrega em IFC2x3, apesar de o IFC4 ser o padrão ISO desde 2018. Veja o que muda no IFC4, quando vale a pena atualizar, e como fazer a transição sem quebrar as ferramentas existentes.",
    seoDescription: "A maioria dos projetos ainda entrega em IFC2x3, mesmo com o IFC4 como padrão ISO desde 2018. O que muda e quando vale a pena atualizar.",
