        type: "p",
        text: "O Artigo 4 do GDPR define dado pessoal como qualquer informação relacionada a uma pessoa natural identificada ou identificável. A maioria dos arquivos IFC não contém dados pessoais no sentido óbvio — eles descrevem edifícios, não pessoas. Mas casos-limite são mais comuns do que as equipes imaginam:",
