        type: "p",
        text: "Segurança é multidimensional, não um atributo único. Serviços na nuvem tipicamente criptografam dados em trânsito (TLS 1.3) e em repouso (AES-256), o que resolve a interceptação passiva. Mas eles introduzem superfícies de ataque que o processamento no navegador elimina por completo: comprometimento no lado do servidor, buckets de armazenamento mal configurados, acesso interno por funcionários do provedor de nuvem, ataques à cadeia de suprimentos na infraestrutura do provedor e violações de residência de dados, caso o servidor esteja localizado fora das jurisdições exigidas contratualmente.",
