        text: "Um arquivo que nunca sai do dispositivo tem exposição zero a qualquer ameaça baseada em rede. A questão de segurança não é 'qual arquitetura é mais segura em termos absolutos?', mas 'quais modelos de ameaça são mais relevantes para este projeto?'. Para o modelo de uma instalação de um Ministério da Defesa, o processamento no navegador elimina completamente o vetor de ameaça do upload. Para um projeto comercial não sensível em que o registro centralizado importa, os controles da nuvem podem ser a escolha certa.",
