        type: "p",
        text: "Software de nível corporativo é definido por confiabilidade, profundidade de recursos e suporte institucional — não pela arquitetura de implantação. Figma, AutoCAD Web, Google Earth e Microsoft Office para a Web são aplicativos de nível corporativo que rodam no navegador usando WebAssembly e APIs web modernas. O mesmo runtime WASM, os mesmos Web Workers e a mesma infraestrutura WebGL que alimentam esses aplicativos também alimentam a validação de IFC no navegador. \"Baseado em navegador\" é uma decisão de arquitetura sobre onde o processamento acontece — não é um teto de qualidade.",
