        text: "A validação roda em um Web Worker separado e não bloqueia a interface — o modelo 3D deve permanecer interativo enquanto a validação roda em segundo plano. Se o processo de carregamento geral parecer lento, verifique se o modelo está carregando do cache do OPFS (rápido) ou sendo processado do zero (mais lento para arquivos grandes). No primeiro carregamento, um arquivo de 200 MB levará de 20 a 40 segundos para ser processado, mesmo localmente. As cargas seguintes a partir do cache levam de 2 a 5 segundos.",
