        text: "O OPFS armazena fragmentos de geometria processada para cada modelo carregado. Para uma equipe de projeto que carrega muitos modelos ao longo de semanas, o cache pode crescer para vários gigabytes. O Gerenciador de Cache do verificador mostra todos os arquivos em cache com seus tamanhos e permite exclusão seletiva. As configurações de armazenamento do navegador também permitem limpar todo o armazenamento da origem. O cache fica armazenado no dispositivo local e não é acessível a nenhum servidor remoto.",
