        type: "p",
        text: "O Solibri é a referência do setor em controle de qualidade sério de modelos BIM. É uma aplicação desktop para Windows e Mac. A versão comercial é usada por grandes empresas de engenharia e construção para verificação de modelo baseada em regras, auditoria de conformidade e coordenação. O Solibri Anywhere é uma versão gratuita e com todos os recursos, disponível para uso não comercial — estudantes, acadêmicos e pessoas aprendendo a ferramenta podem usá-la sem custo.",
