        text: "Enquanto as 44 regras do IFC Viewer Online cobrem os problemas de qualidade de IFC mais comuns já de saída, o motor de regras do Solibri foi pensado para a criação de regras personalizadas: verificação de afastamentos estruturais, completude de propriedades do COBie, convenções de nomenclatura específicas da organização e requisitos de hierarquia espacial que vão além de qualquer conjunto fixo de regras. Se a sua organização tem requisitos BIM sob medida codificados em um BEP ou EIR, a capacidade de criação de regras do Solibri não tem igual na faixa gratuita ou quase gratuita.",
