        type: "p",
        text: "O BIMVision é um visualizador de IFC gratuito para desktop Windows, desenvolvido pela Datacomp. É amplamente usado na Europa Central e Oriental como o visualizador de IFC gratuito padrão para equipes que precisam de inspeção básica de modelo sem orçamento. A ferramenta não tem restrições comerciais no uso gratuito — uma organização inteira pode instalá-la sem licença. Foi pensada para inspeção e apresentação, não para validação ou coordenação.",
