        type: "p",
        text: "O BIMcollab Zoom é um visualizador de IFC desktop da BIMcollab, a empresa por trás da plataforma de gestão de BCF BIMcollab Cloud. O propósito principal da ferramenta é a coordenação de modelo liderada por BCF — ela foi pensada para funcionar junto com o BIMcollab Cloud, sincronizando issues em tempo real entre disciplinas. Ela renderiza a geometria do IFC e permite que as equipes criem, comentem e resolvam issues em BCF direto na visualização do modelo.",
