            "Configure Psets personalizados para carregar os metadados do EIR nos modelos (templates) do software de autoria",
            "Rode a verificação L3 por IDS em cada marco de fase, não apenas na entrega final",
            "Prevenção: use o IDS como a versão legível por máquina dos requisitos de dados do EIR",
