        type: "p",
        text: "Os requisitos de Nível de Desenvolvimento (LOD) e Nível de Informação (LOI) variam por fase do projeto e tipo de elemento. Na fase de construção, elementos estruturais devem ter LOD 400 (geometria pronta para fabricação e propriedades de material completas), enquanto acabamentos arquitetônicos ainda podem estar em LOD 300. Inconsistências — uma parede com geometria em LOD 200 e dados de propriedade em LOD 400, ou vice-versa — causam imprecisões no QTO e falhas nos marcos de fase.",
